let calendarMonth=null;
const sharedCalendarURL='https://ahmedezeldin.github.io/sso-uofa/sso-events.ics';
function subscriptionPanel(){return `<div class="calendar-subscribe"><div><div class="eyebrow">${tr('Subscribe once. Stay in the loop.','اشترك مرة وخليك على اطلاع.')}</div><h3>${tr('Keep SSO on your calendar.','خلي المنظمة في تقويمك.')}</h3><p>${tr('Subscribe to receive new events and schedule changes after publication. Your calendar app controls how quickly updates appear.','اشترك لاستقبال الفعاليات الجديدة وتغييرات المواعيد بعد نشرها. سرعة ظهور التحديثات تعتمد على تطبيق التقويم.')}</p><div class="calendar-subscribe-actions"><a class="button" href="${sharedCalendarURL.replace('https:','webcal:')}">${tr('Apple Calendar / calendar app','تقويم آبل / تطبيق التقويم')} </a></div></div><div><details open><summary>Google Calendar</summary><p>${tr('On a computer: Google Calendar → Other calendars → + → From URL. Paste the link and choose Add calendar. It will appear on devices using that account.','على الكمبيوتر: تقويم جوجل ← تقاويم أخرى ← + ← من عنوان URL. الصق الرابط واختر إضافة تقويم. سيظهر على الأجهزة التي تستخدم حسابك.')}</p><a class="textlink" href="https://support.google.com/calendar/answer/37100" target="_blank" rel="noopener noreferrer">${tr('Google instructions','إرشادات جوجل')} </a></details><details><summary>Outlook / ${tr('other apps','تطبيقات أخرى')}</summary><p>${tr('Choose Subscribe from web or Add calendar by URL, then paste the link. Use a subscription to receive updates.','اختر الاشتراك من الويب أو إضافة تقويم عبر الرابط، ثم الصق الرابط لاستقبال التحديثات.')}</p></details><label for="calendar-feed-link">${tr('Subscription link','رابط الاشتراك')}</label><div class="calendar-link-row"><input id="calendar-feed-link" readonly dir="ltr" value="${sharedCalendarURL}"><button class="calendar-copy-button" id="calendar-copy">${tr('Copy','نسخ')}</button></div><p id="calendar-copy-status" role="status"></p></div></div>`}
function bindSubscription(){const help=document.querySelector('.calendar-help');help.textContent=tr('Subscribe below for ongoing updates. The .ics download is a one-time snapshot. Dates without a verified time appear as all-day entries.','اشترك أدناه لاستقبال التحديثات. تنزيل .ics نسخة لمرة واحدة. المواعيد دون وقت موثّق تظهر كيوم كامل.');help.nextElementSibling.remove();const layout=document.querySelector('.calendar-layout');layout.insertAdjacentHTML('beforebegin',subscriptionPanel());document.querySelector('#calendar-copy').onclick=async()=>{try{await navigator.clipboard.writeText(sharedCalendarURL);document.querySelector('#calendar-copy-status').textContent=tr('Link copied. Paste it into your calendar subscription settings.','تم نسخ الرابط. الصقه في إعدادات الاشتراك بتقويمك.')}catch{document.querySelector('#calendar-feed-link').focus();document.querySelector('#calendar-feed-link').select();document.querySelector('#calendar-copy-status').textContent=tr('Select and copy the link below.','حدد الرابط أدناه وانسخه.')}}}
function campusToday(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Edmonton',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>p.find(x=>x.type===k).value;return get('year')+'-'+get('month')+'-'+get('day')}
function datedEvents(){return events.filter(e=>e.calendarDate).sort((a,b)=>a.calendarDate.localeCompare(b.calendarDate))}
function calendarSection(){return `<section class="section club-calendar" id="calendar" aria-labelledby="calendar-heading"><div class="sectiontop"><div><div class="eyebrow">${tr('Make room for community','خصص وقتاً للمة')}</div><h2 id="calendar-heading">${tr('Your SSO calendar.','تقويم المنظمة.')}</h2><p>${tr('Browse dated events and add them to your own calendar. Current entries are past events; new dates will appear once confirmed by the club.','استعرض الفعاليات المؤرخة وأضفها إلى تقويمك. الإدخالات الحالية فعاليات سابقة؛ ستظهر المواعيد الجديدة عند تأكيدها من المنظمة.')}</p></div><button class="button light" id="calendar-download">${tr('Download all dated events (.ics)','تنزيل كل الفعاليات المؤرخة (.ics)')} </button></div><p class="calendar-help">${tr('Calendar files work with Apple Calendar and Outlook, and can be imported into Google Calendar. This is a one-time import; updates won’t sync automatically. Dates without a verified time are all-day placeholders.','تعمل ملفات التقويم مع تقويم آبل وأوتلوك، ويمكن استيرادها إلى تقويم جوجل. الاستيراد لمرة واحدة؛ لا تتم مزامنة التحديثات تلقائياً. تُعرض المواعيد دون وقت موثّق كإدخالات ليوم كامل.')}</p><a class="textlink" style="font-size:11px" href="https://support.google.com/calendar/answer/37118" target="_blank" rel="noopener noreferrer">${tr('How to import into Google Calendar','طريقة الاستيراد إلى تقويم جوجل')} </a><div class="calendar-layout"><div class="calendar-panel"><div class="calendar-toolbar"><button id="calendar-prev" aria-label="${tr('Previous month','الشهر السابق')}">‹</button><h3 id="calendar-month"></h3><button id="calendar-next" aria-label="${tr('Next month','الشهر التالي')}">›</button><button id="calendar-today">${tr('Today','اليوم')}</button></div><div id="calendar-grid" class="calendar-grid"></div></div><div id="calendar-agenda" class="calendar-agenda" aria-live="polite"></div></div><details class="calendar-archive"><summary>${tr('All event dates & undated highlights','كل مواعيد الفعاليات والقصص غير المؤرخة')}</summary><div id="calendar-all"></div></details></section>`}
function formatEventDate(iso){return new Intl.DateTimeFormat(lang==='ar'?'ar-CA':'en-CA',{timeZone:'UTC',year:'numeric',month:'long',day:'numeric'}).format(new Date(iso+'T12:00:00Z'))}
function eventCalendarCard(e){return `<article class="calendar-entry"><span class="tag">${e.calendarDate?formatEventDate(e.calendarDate)+' · '+(e.calendarDate<campusToday()?tr('Past','سابق'):tr('Scheduled','مجدول')):tr('Date not confirmed','التاريخ غير مؤكد')}</span><h3>${t(e.title)}</h3><p>${t(e.desc)}</p><div class="calendar-entry-actions"><button class="textlink" data-calendar-detail="${e.id}">${tr('Details','التفاصيل')} </button>${e.calendarDate?`<button class="textlink" data-calendar-add="${e.id}">${tr('Add to my calendar (.ics)','أضف إلى تقويمي (.ics)')} </button><button class="textlink" data-calendar-jump="${e.calendarDate.slice(0,7)}">${tr('Show month','عرض الشهر')}</button>`:''}</div></article>`}
function drawCalendar(){if(!calendarMonth)calendarMonth=campusToday().slice(0,7);const [y,m]=calendarMonth.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)),days=new Date(Date.UTC(y,m,0)).getUTCDate(),inMonth=datedEvents().filter(e=>e.calendarDate.startsWith(calendarMonth));document.querySelector('#calendar-month').textContent=new Intl.DateTimeFormat(lang==='ar'?'ar-CA':'en-CA',{timeZone:'UTC',month:'long',year:'numeric'}).format(first);
const weekdays=Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(lang==='ar'?'ar-CA':'en-CA',{weekday:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,0,4+i))));
document.querySelector('#calendar-grid').innerHTML=weekdays.map(w=>'<div class="calendar-weekday">'+w+'</div>').join('')+Array.from({length:first.getUTCDay()},()=>'<div class="calendar-blank" aria-hidden="true"></div>').join('')+Array.from({length:days},(_,i)=>{const iso=calendarMonth+'-'+String(i+1).padStart(2,'0'),list=inMonth.filter(e=>e.calendarDate===iso);return '<div class="calendar-day '+(iso===campusToday()?'is-today':'')+'"><span>'+new Intl.NumberFormat(lang==='ar'?'ar':'en').format(i+1)+'</span>'+list.map(e=>'<button data-calendar-detail="'+e.id+'" aria-label="'+escapeOnboard(t(e.title)+' · '+formatEventDate(iso))+'">'+escapeOnboard(t(e.title))+'</button>').join('')+'</div>'}).join('');
document.querySelector('#calendar-agenda').innerHTML='<h3>'+tr('This month','هذا الشهر')+'</h3>'+(inMonth.length?inMonth.map(eventCalendarCard).join(''):'<p class="calendar-empty">'+tr('No confirmed events listed for this month. Check SSO’s announcements or browse the archive below.','لا توجد فعاليات مؤكدة مدرجة لهذا الشهر. راجع إعلانات المنظمة أو استعرض الأرشيف أدناه.')+'</p><a class="textlink" href="https://www.instagram.com/sso.uofa/" target="_blank" rel="noopener noreferrer">'+tr('SSO announcements','إعلانات المنظمة')+' </a>');
document.querySelector('#calendar-all').innerHTML=events.map(eventCalendarCard).join('');
document.querySelectorAll('[data-calendar-detail]').forEach(b=>b.onclick=()=>openEvent(b.dataset.calendarDetail));document.querySelectorAll('[data-calendar-add]').forEach(b=>b.onclick=()=>downloadCalendar([events.find(e=>e.id===b.dataset.calendarAdd)]));document.querySelectorAll('[data-calendar-jump]').forEach(b=>b.onclick=()=>{calendarMonth=b.dataset.calendarJump;drawCalendar();document.querySelector('#calendar-month').scrollIntoView({block:'center',behavior:'smooth'})})}
function icsEscape(s){return s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function calendarFile(list){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SSO UofA//Community Calendar//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:SSO UofA Events','X-WR-TIMEZONE:America/Edmonton'];for(const e of list){const start=e.calendarDate.replaceAll('-',''),next=new Date(e.calendarDate+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);const end=next.toISOString().slice(0,10).replaceAll('-','');lines.push('BEGIN:VEVENT','UID:sso-'+e.id+'@ualberta-sudanese-club.classybirch16.chatgpt.site','DTSTAMP:'+(e.calendarRevision?.stamp||new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')),'SEQUENCE:'+(e.calendarRevision?.sequence||0),'DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+icsEscape(t(e.title)),'DESCRIPTION:'+icsEscape(t(e.desc)+' '+tr('Date-only archive entry. Start time and venue not verified. See the club source.','إدخال أرشيفي بالتاريخ فقط. وقت البداية والمكان غير موثّقين. راجع مصدر المنظمة.')+' '+e.source),'URL:'+e.source,'TRANSP:TRANSPARENT','END:VEVENT')}lines.push('END:VCALENDAR');return lines.map(line=>{const out=[];let part='',size=0;for(const ch of line){const bytes=new TextEncoder().encode(ch).length;if(size+bytes>73){out.push(part);part=' '+ch;size=1+bytes}else{part+=ch;size+=bytes}}out.push(part);return out.join('\r\n')}).join('\r\n')+'\r\n'}
function downloadCalendar(list){const url=URL.createObjectURL(new Blob([calendarFile(list)],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=list.length===1?'sso-'+list[0].id+'.ics':'sso-events.ics';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindCalendar(){drawCalendar();bindSubscription();const shift=n=>{const [y,m]=calendarMonth.split('-').map(Number),d=new Date(Date.UTC(y,m-1+n,1));calendarMonth=d.toISOString().slice(0,7);drawCalendar()};document.querySelector('#calendar-prev').onclick=()=>shift(-1);document.querySelector('#calendar-next').onclick=()=>shift(1);document.querySelector('#calendar-today').onclick=()=>{calendarMonth=campusToday().slice(0,7);drawCalendar()};document.querySelector('#calendar-download').onclick=()=>downloadCalendar(datedEvents())}
